def test_circuit_opens_on_repeated_failure() -> None:
    sl = SkipList(failure_threshold=3, recovery_timeout=60)
    sl.push(1)
    # Force failures by popping from an empty list repeatedly.
    # Catch both IndexError (empty list) and CircuitBreakerOpenError (circuit
    # already open) so the loop can run to completion.
    for _ in range(3):
        try:
            sl.pop()
            sl.pop()
        except (IndexError, CircuitBreakerOpenError):
            pass
    assert sl.circuit_state == CircuitState.OPEN
    try:
        sl.push(99)
        assert False, "expected CircuitBreakerOpenError"
    except CircuitBreakerOpenError:
        pass
